    changed: 2,
    pending: 0,
    failed: 0,
  },
});

expect(await publicationEvents()).toEqual([
  expect.objectContaining({ node_id: "page-64", status: "refreshed", attempts: 1 }),
  expect.objectContaining({ node_id: "page-80", status: "refreshed", attempts: 1 }),
]);

expect(runs.at(-1)?.body).toMatchObject({
  status: "reconciled",
  entries: {
    "/about-us/": { change: "moved", outcome: "refreshed" },
    "/2026/09/hello/": { change: "removed", outcome: "refreshed" },
  },
});

expect(runs.at(-1)?.body).toMatchObject({
  status: "reconciled",
  entries: {
    "/news/": { change: "new", outcome: "refreshed" },
    "/about-us/": { change: "moved", outcome: "refreshed" },
    "/2026/09/hello/": { change: "removed", outcome: "refreshed" },
  },
});

expect(runs.at(-1)?.body).toMatchObject({
  status: "reconciled",
  shared: {
    home: { outcome: "promoted" },
    chrome: { outcome: "promoted" },
    design: { outcome: "promoted" },
  },
});

expect(run.body).toMatchObject({
  status: "reconciled",
  shared: {
    home: { outcome: "unchanged" },
    chrome: { outcome: "unchanged" },
    design: { outcome: "unchanged" },
  },
  checked: 3,
  changed: 0,
});

expect(failed[0]?.body).toMatchObject({
  status: "failed",
  listing: { outcome: "kept", failure: { reason: "network" } },
  shared: { home: { outcome: "kept" }, chrome: { outcome: "kept" }, design: { outcome: "kept" } },
  failure: { reason: "network" },
});

expect(noList).toMatchObject({
  status: 503,
  body: { status: "failed", listing: { outcome: "kept", failure: { reason: "http" } } },
});

expect(unread.body).toMatchObject({
  status: "failed",
  entries: {
    "/about/": { change: "changed", outcome: "kept", failure: { reason: "http" } },
    "/2026/09/hello/": { change: "removed", outcome: "refreshed" },
  },
});

expect((await publicationEvents()).filter(({ node_id }) => node_id === "page-64")).toEqual([
  { ...failedEvent, status: "refreshed", attempts: 2, reason: null },
]);

expect(runs.every(({ status, body }) => status === 200 && !("/about/" in body.entries))).toBe(
  true,
);

expect(await publicationEvents()).toEqual([
  expect.objectContaining({ node_id: "page-64", status: "refreshed", attempts: 2 }),
]);

expect(
  [unsigned, anotherKey, anotherSite, malformed, disabled].map(({ status }) => status),
).toEqual([401, 401, 403, 400, 403]);

expect(report).toMatchObject({
  ready: true,
  refreshed: true,
  languages: {
    en: {
      home: { outcome: "promoted", state: "published" },
      chrome: { outcome: "promoted", state: "published" },
    },
  },
});

expect(
  queries(fetchMock, "HomePage").map(([, init]) => JSON.parse(init.body as string).variables),
).toEqual(expect.arrayContaining([{ uri: "/en/", language: "EN" }]));

expect(
  queries(fetchMock, "SiteChrome").map(([, init]) => JSON.parse(init.body as string).variables),
).toEqual([{ location: "PRIMARY" }, { location: "PRIMARY", language: "EN" }]);

expect(body).toMatchObject({
  status: "refreshed",
  languages: { en: { home: { outcome: "promoted", state: "published" } } },
  entries: {},
});

expect(body).toMatchObject({
  status: "refreshed",
  setting: "menus",
  language: "en",
  languages: { en: { chrome: { outcome: "promoted", state: "published" } } },
});

expect(body).toMatchObject({
  status: "refreshed",
  languages: { en: { home: { outcome: "promoted", state: "published" } } },
});

expect(body).toMatchObject({
  status: "refreshed",
  chrome: { outcome: "promoted" },
  languages: { en: { chrome: { outcome: "promoted" } } },
});

expect(body).toMatchObject({
  status: "failed",
  languages: { en: { chrome: { outcome: "kept", failure: { reason: "network" } } } },
});

expect(first).toMatchObject({
  status: 503,
  body: {
    ready: false,
    refreshed: false,
    languages: { en: { chrome: { outcome: "kept" } } },
  },
});

expect(body.store).toMatchObject({
  home: "published",
  chrome: "published",
  languages: { en: { home: null, chrome: "published" } },
});

expect(body).toMatchObject({
  status: "reconciled",
  shared: {
    home: { outcome: "unchanged" },
    chrome: { outcome: "unchanged" },
    design: { outcome: "unchanged" },
    languages: { en: { home: { outcome: "unchanged" }, chrome: { outcome: "unchanged" } } },
  },
});

expect(body).toMatchObject({
  status: "reconciled",
  shared: {
    home: { outcome: "unchanged" },
    chrome: { outcome: "unchanged" },
    languages: { en: { home: { outcome: "promoted" }, chrome: { outcome: "promoted" } } },
  },
  entries: { "/en/about/": { change: "changed", outcome: "refreshed" } },
});

check(
  "the Frontend's migrations apply to the local D1 store",
  migrate.status === 0,
  migrate.stderr,
);

check(
  "a never-refreshed Site's entry is a 503",
  coldEntry.status === 503,
  `HTTP ${coldEntry.status}`,
);

check(
  "a refresh without the token is refused",
  anonymous.status === 401,
  `HTTP ${anonymous.status}`,
);

check(
  "gq frontend refresh stores the homepage",
  first.code === 0 && first.report?.ready === true,
  JSON.stringify(first.report) + first.stderr,
);

check(
  "the homepage is served with its menu, logo and design presets",
  prepared.status === 200 && served(prepared.html),
  `HTTP ${prepared.status}`,
);

check(
  "with the CMS down the homepage is still served",
  outage.status === 200 && served(outage.html),
  `HTTP ${outage.status}`,
);

check(
  "and so is the entry",
  outageEntry.status === 200 && servedEntry(outageEntry.html),
  `HTTP ${outageEntry.status}`,
);

check(
  "an entry the store never held is a 503, not a 404",
  uncached.status === 503,
  `HTTP ${uncached.status}`,
);

check(
  "a refresh during the outage fails and keeps it",
  failed.code === 1 && failed.report?.home?.outcome === "kept" && failed.report?.ready === true,
  JSON.stringify(failed.report),
);

check(
  "after a Worker restart, with the CMS still down and its content a year old, it is still served",
  restarted.status === 200 && served(restarted.html),
  `HTTP ${restarted.status}`,
);

check(
  "and so is the entry",
  restartedEntry.status === 200 && servedEntry(restartedEntry.html),
  `HTTP ${restartedEntry.status}`,
);

check(
  "after a rebuilt redeploy, with the CMS still down, it is still served",
  redeployed.status === 200 && served(redeployed.html),
  `HTTP ${redeployed.status}`,
);

check(
  "once the CMS is back, a refresh serves its changes",
  recovered.code === 0 && served(updated.html, "Spring at Acme", "Contact"),
  JSON.stringify(recovered.report),
);

check(
  "an entry the store never held is looked up while the CMS is healthy",
  lookedUp.status === 200 && servedEntry(lookedUp.html, "Write to us.", "Contact"),
  `HTTP ${lookedUp.status}`,
);

check(
  "gq frontend refresh --uri serves a new publication through an outage",
  targeted.code === 0 && news.status === 200 && servedEntry(news.html, "We launched.", "Contact"),
  JSON.stringify(targeted.report) + targeted.stderr,
);

check(
  "gq frontend events check: the Worker accepts this Site's signed events",
  accepted.code === 0 && accepted.json?.accepted === true,
  accepted.stdout + accepted.stderr,
);

check(
  "and refuses events signed with another key",
  refused.code === 1 && refused.json?.status === 401,
  refused.stdout + refused.stderr,
);

check(
  "and the other entries are still served",
  kept.status === 200 && kept.html.includes("Write to us."),
  `HTTP ${kept.status}`,
);

check(
  "after a Worker restart it is still a 404, and a delayed older publication is superseded",
  stale.status === 200 && stale.body?.status === "superseded" && afterRestart.status === 404,
  `${JSON.stringify(stale.body)} HTTP ${afterRestart.status}`,
);

check(
  "a whole-Site refresh from a CMS that still returns it doesn't restore it",
  whole.report?.entries?.["/news/"]?.outcome === "withdrawn" && afterRefresh.status === 404,
  `${JSON.stringify(whole.report?.entries?.["/news/"])} HTTP ${afterRefresh.status}`,
);

check(
  "gq site check: WordPress installed without WPGraphQL active is not ready",
  withoutGraphql.wordpress?.status === "not-ready" &&
    /isn't a WPGraphQL endpoint/u.test(withoutGraphql.wordpress.detail),
  JSON.stringify(withoutGraphql),
);

check(
  "and every other field the Frontend reads is valid on real WPGraphQL",
  (validation.errors ?? []).length > 0 && unexpected.length === 0,
  JSON.stringify(unexpected),
);

check(
  "the Frontend's migrations apply to the local D1 store",
  migrate.status === 0,
  migrate.stderr,
);

check(
  "wp gq-events check: the Frontend accepts the CMS's signed events",
  checked.code === 0 && /accepts acme's events/u.test(checked.stdout),
  checked.stdout + checked.stderr,
);

check(
  "an update reaches visitors without a deploy",
  updated.status === 200 && updated.html.includes("We launched today."),
  `HTTP ${updated.status}`,
);

check(
  "a menu shown nowhere sends nothing; assigning it to the primary location sends a settings event, and every page shows it through an outage",
  unlocated === null &&
    menus?.delivery?.status === "refreshed" &&
    menus.event.setting === "menus" &&
    pages.every(
      ({ status, html }) => status === 200 && /<a href="\/about\/"[^>]*>Contact<\/a>/u.test(html),
    ),
  `${JSON.stringify(menus)} ${pages.map(({ status }) => status)}`,
);

check(
  "changing the site logo sends a settings event, and every page shows it",
  logo?.delivery?.status === "refreshed" &&
    pages.every(({ html }) => html.includes('src="https://media.example/logo-2026.svg"')),
  JSON.stringify(logo),
);

check(
  "changing the tagline and the site icon sends identity events: the homepage shows the tagline, every page the icon",
  identity?.delivery?.status === "refreshed" &&
    pages[0].html.includes('<meta name="description" content="Better things">') &&
    pages.every(({ html }) =>
      html.includes('<link rel="icon" href="https://media.example/icon.png">'),
    ),
  JSON.stringify(identity),
);

check(
  "saving the palette through the global-styles REST route sends a design event, and every page uses it",
  saved.endsWith("200") &&
    design?.delivery?.status === "refreshed" &&
    pages.every(
      ({ html }) =>
        html.includes("--wp--preset--color--brand:#0a0") && !html.includes("brand:#c00"),
    ),
  `${saved} ${JSON.stringify(design)}`,
);

check(
  "with the Frontend down, publishing still succeeds, within the event's time bound",
  offline.code === 0 && status === "publish" && elapsed < 20_000,
  `exit ${offline.code}, ${status}, ${elapsed} ms: ${offline.stderr}`,
);

check(
  "wp gq-events status lists it",
  JSON.parse(pending.stdout || "[]").some(
    (row) => String(row.post) === id && row.status === "failed",
  ),
  pending.stdout + pending.stderr,
);

check(
  "meanwhile visitors get the last good publication",
  stale.status === 200 && stale.html.includes("We launched today."),
  `HTTP ${stale.status}`,
);

check(
  "in production without the key, publishing succeeds and records why nothing was sent",
  unconfigured?.delivery?.status === "failed" &&
    unconfigured.delivery.reason === "not-configured",
  JSON.stringify(unconfigured?.delivery),
);

check(
  "a new page is delivered at once",
  (await recorded(pricing))?.delivery?.status === "refreshed",
);

check(
  "once the CMS is back, the next due run delivers both, through a later outage",
  restored.code === 0 &&
    afterRestore.every(
      (record) => record?.delivery?.status === "refreshed" && record.delivery.attempts === 3,
    ) &&
    fresh.html.includes("Prices v3.") &&
    pages[0].html.includes('<meta name="description" content="Even better things">'),
  restored.stdout + restored.stderr + JSON.stringify(afterRestore.map((r) => r?.delivery)),
);

check(
  "an operator's retry delivers it",
  operator.code === 0 && (await recorded(pricing))?.delivery?.status === "refreshed",
  operator.stdout + operator.stderr,
);

check(
  "a run while another holds the lock sends nothing",
  overlapping.code === 0 && /Another run is sending events/u.test(overlapping.stdout),
  overlapping.stdout + overlapping.stderr,
);

check(
  "wp gq-events delays shows when the scheduler last ran",
  /The retry scheduler last ran at/u.test(table.stdout),
  table.stdout + table.stderr,
);

check(
  "the entry is served before it is withdrawn",
  (await visit(port, "/launch/")).html.includes("Published again."),
);

check(
  "republishing serves it again",
  republished.status === 200 && republished.html.includes("Published again."),
  `HTTP ${republished.status}`,
);

check(
  "password-protecting it withdraws it",
  protectedEvent?.event?.action === "withdraw" && protectedVisit.status === 404,
  `${JSON.stringify(protectedEvent?.event)} HTTP ${protectedVisit.status}`,
);

check(
  "deleting a published page outright withdraws it, and leaves no record once refreshed",
  deleted.status === 404 && !(team in (await deletedOption())),
  `HTTP ${deleted.status}`,
);

check(
  "gq site check: once the scheduler has reconciled, the Frontend and its delivery are ready, through the CMS outage",
  reconciledReadiness.every(({ status }) => status !== "not-ready") &&
    byName(reconciledReadiness).reconciliation?.status === "ok",
  describeChecks(reconciledReadiness),
);

check(
  "wp gq-events reconcile reconciles at once once the CMS is back",
  manual.code === 0 && /matches WordPress/u.test(manual.stdout),
  manual.stdout + manual.stderr,
);

check(
  "a real cron running the crontab gq ploi events installs delivers a missed publication, without visits or a retry by hand",
  missed?.delivery?.status === "failed" &&
    byCron?.event?.id === missed.event.id &&
    byCron?.delivery?.status === "refreshed" &&
    byCron.delivery.attempts === 2 &&
    scheduled.ranAt > 0 &&
    (await visit(port, "/pricing/")).html.includes("Prices by cron."),
